const SLIDING_WINDOW_MS = 30 * 60 * 1000;
const MAX_REFRESH_TOKEN_AGE_MS = 7 * 24 * 60 * 60 * 1000;

app.post('/api/auth/refresh', async (req, res) => {
  const { refreshToken } = req.body;

  if (!refreshToken) {
    return res.status(401).json({ message: 'Refresh token required' });
  }

  const hashedToken = crypto.createHash('sha256').update(refreshToken).digest('hex');
  const storedToken = await RefreshToken.findOne({ token: hashedToken });

  if (!storedToken || storedToken.revoked) {
    return res.status(403).json({ message: 'Invalid refresh token' });
  }

  const now = Date.now();
  const tokenAge = now - storedToken.createdAt.getTime();
  const timeRemaining = storedToken.expiresAt.getTime() - now;
  let newRefreshToken = refreshToken;

  if (timeRemaining < SLIDING_WINDOW_MS && tokenAge < MAX_REFRESH_TOKEN_AGE_MS) {
    storedToken.revoked = true;
    await storedToken.save();

    newRefreshToken = generateSecureToken();
    const newHashedToken = crypto.createHash('sha256').update(newRefreshToken).digest('hex');

    await RefreshToken.create({
      token: newHashedToken,
      familyId: storedToken.familyId,
      userId: storedToken.userId,
      expiresAt: new Date(now + SLIDING_WINDOW_MS),
      createdAt: new Date(now)
    });
  }

  const accessToken = generateAccessToken(storedToken.userId);
  res.json({ accessToken, refreshToken: newRefreshToken });
});

function useAuth() {
  const [accessToken, setAccessToken] = useState<string | null>(null);
  const [refreshToken, setRefreshToken] = useState<string | null>(null);

  const refreshAccessToken = useCallback(async () => {
    if (!refreshToken) return null;

    try {
      const res = await fetch('/api/auth/refresh', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ refreshToken })
      });

      if (!res.ok) throw new Error('Refresh failed');

      const data = await res.json();
      setAccessToken(data.accessToken);
      if (data.refreshToken) {
        setRefreshToken(data.refreshToken);
      }
      return data.accessToken;
    } catch (err) {
      setAccessToken(null);
      setRefreshToken(null);
      return null;
    }
  }, [refreshToken]);

  return { accessToken, refreshToken, refreshAccessToken };
}

